# Read-only. Run elevated. Needs the October 2026 (or later) Windows security update on targets.
$servers = @($env:COMPUTERNAME)   # or: Get-Content .\servers.txt
$rows = foreach ($s in $servers) {
  $pol = Invoke-Command -ComputerName $s -ScriptBlock {
    $gp  = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Policies' -Name RefsRemovableDeviceMountPolicy -ErrorAction SilentlyContinue).RefsRemovableDeviceMountPolicy
    $loc = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' -Name RefsRemovableDeviceMountPolicy -ErrorAction SilentlyContinue).RefsRemovableDeviceMountPolicy
    if ($null -ne $gp) { "GPO=$gp" } elseif ($null -ne $loc) { "Local=$loc" } else { 'NotSet (default Audit until Jan 2027)' }
  } -ErrorAction SilentlyContinue
  $ev = Get-WinEvent -ComputerName $s -FilterHashtable @{ LogName='System'; ProviderName='ReFS'; Id=524 } -ErrorAction SilentlyContinue
  if ($ev) {
    $ev | ForEach-Object { [pscustomobject]@{ Server=$s; LastSeen=$_.TimeCreated; Policy=$pol; Message=($_.Message -replace '\s+',' ') } }
  } else {
    [pscustomobject]@{ Server=$s; LastSeen=$null; Policy=$pol; Message='No ReFS 524 events' }
  }
}
$rows | Sort-Object Server, Message -Unique | Export-Csv .\refs-removable-audit.csv -NoTypeInformation
$rows | Format-Table Server, LastSeen, Policy, Message -AutoSize
